package com.bank.loans.adapters.out.jdbc;

import com.bank.loans.domain.port.SimulationRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDateTime;

/** JDBC adapter of the SimulationRepository port. */
@Repository
public class JdbcSimulationRepository implements SimulationRepository {

    private final JdbcTemplate jdbcTemplate;

    public JdbcSimulationRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Override
    public int save(BigDecimal monto, Integer plazo, BigDecimal tasaAnual, BigDecimal cuotaMensual,
                    BigDecimal totalAPagar, LocalDateTime fechaHora) {
        // The target table declares numero_correlativo as a plain INTEGER key (no identity),
        // so the next correlative is obtained from the table itself.
        Integer next = jdbcTemplate.queryForObject(
                "SELECT COALESCE(MAX(numero_correlativo), 0) + 1 FROM simulation",
                Integer.class);
        int numeroCorrelativo = next == null ? 1 : next;

        jdbcTemplate.update(
                "INSERT INTO simulation (numero_correlativo, monto, plazo, tasa_anual, cuota_mensual, "
                        + "total_a_pagar, fecha_hora) VALUES (?, ?, ?, ?, ?, ?, ?)",
                numeroCorrelativo,
                monto,
                plazo,
                tasaAnual,
                cuotaMensual,
                totalAPagar,
                fechaHora == null ? null : Timestamp.valueOf(fechaHora));

        return numeroCorrelativo;
    }
}
